(async()=>{const id=document.body.dataset.productId;const products=await(await fetch('/data/catalog.json')).json();const p=products.find(p=>p.id===id);if(!p)return;if(location.pathname.startsWith('/p/')&&matchMedia('(max-width:991px)').matches&&p.mobileOriginalPage){location.replace('/pm/'+id+'.html');return}let choices={};let currentPrice=p.price;const main=document.querySelector('main');let quantity=1;const capturedPrice=main.querySelector('[aria-label="Preço à vista"]')?.textContent;const priceMatch=capturedPrice?.match(/R\$\s*([\d.]+,\d{2})/);if(priceMatch)currentPrice=Math.round(Number(priceMatch[1].replaceAll('.','').replace(',','.'))*100);
const parsePrice=t=>{const m=[...(t||'').matchAll(/R\$\s*([\d.]+,\d{2})/g)].at(-1);return m?Math.round(Number(m[1].replaceAll('.','').replace(',','.'))*100):null};
let variants=null;try{const response=await fetch('/data/variants/'+id+'.json');if(response.ok)variants=await response.json()}catch{}const sourceGroups=variants?.groups||p.groups||[];
main.querySelectorAll('[aria-haspopup="listbox"]').forEach((control,index)=>{if(String(control.className).includes('ts-'))return;const holder=control.parentElement;let group=holder.querySelector('[role="listbox"]');if(group)return;const label=control.textContent.trim();const data=sourceGroups.find(g=>g.name===label)||sourceGroups[index]||(sourceGroups.length===1?sourceGroups[0]:null);if(!data?.options?.length){control.dataset.unresolvedVariant='true';return}group=document.createElement('ul');group.setAttribute('role','listbox');group.setAttribute('aria-label',data.name);data.options.forEach(option=>{const li=document.createElement('li');li.className='opcao-item';li.setAttribute('role','option');li.tabIndex=0;li.setAttribute('aria-disabled',String(!!option.disabled));li.setAttribute('aria-selected',String(!!option.selected));li.textContent=option.name;group.append(li)});holder.append(group);});
document.querySelectorAll('main [role="radiogroup"],main [role="listbox"]').forEach((group,index)=>{if(group.id.startsWith('ts-'))return;const name=group.getAttribute('aria-label')||'Opção '+(index+1);const list=group.getAttribute('role')==='listbox';let button=list?group.parentElement.querySelector('[aria-haspopup="listbox"]'):null;if(list){group.dataset.localList='true';group.hidden=true;if(button){button.setAttribute('aria-expanded','false');button.onclick=()=>{group.hidden=!group.hidden;button.setAttribute('aria-expanded',String(!group.hidden))}}}for(const item of group.querySelectorAll('[role="option"],[role="radio"]')){const label=item.querySelector('.opcao-nome')?.textContent.trim()||item.getAttribute('aria-label')||item.textContent.trim();if(item.getAttribute('aria-selected')==='true'||item.getAttribute('aria-checked')==='true')choices[name]=label;item.onclick=()=>{if(item.getAttribute('aria-disabled')==='true')return;choices[name]=label;const heading=group.closest('.flavorSelector,.weightCards')?.querySelector('strong');if(heading)heading.textContent=label;group.querySelectorAll('[role="option"],[role="radio"]').forEach(e=>{e.setAttribute(list?'aria-selected':'aria-checked',String(e===item));e.classList.toggle('active',e===item)});if(button){button.textContent=label;button.setAttribute('aria-expanded','false');group.hidden=true}const value=parsePrice(item.innerText);if(value){currentPrice=value;const priceNode=document.querySelector('main [role="group"][aria-label="Preço à vista"]');if(priceNode)priceNode.textContent=(value/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}document.querySelector('.local-selection-error')?.remove()};item.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();item.click()}}}});
main.querySelectorAll('button,input[type=button]').forEach(b=>{if(!/^comprar$/i.test((b.textContent||b.value||'').trim()))return;b.addEventListener('click',e=>{e.preventDefault();e.stopImmediatePropagation();const groups=[...main.querySelectorAll('[role="radiogroup"],[role="listbox"]')].filter(g=>!g.id.startsWith('ts-'));const missing=groups.find((g,i)=>!choices[g.getAttribute('aria-label')||'Opção '+(i+1)]);const unresolved=main.querySelector('[data-unresolved-variant]');if(missing||unresolved||!currentPrice){let err=document.querySelector('.local-selection-error');if(!err){err=document.createElement('p');err.className='local-selection-error';err.setAttribute('role','alert');b.before(err)}err.textContent=unresolved?'As opções deste produto ainda estão sendo conferidas.':missing?'Selecione a variação do produto antes de comprar.':'Preço ainda não confirmado.';err.scrollIntoView({block:'center',behavior:'smooth'});return}const q=main.querySelector('input[type=number]');const count=Math.max(1,Math.min(99,Number(q?.value)||quantity));if(window.GrowthStore)window.GrowthStore.add({id,options:{...choices},quantity:count,price:currentPrice,image:p.images[0]});},true)});

main.querySelectorAll('button[aria-label="Aumentar quantidade"],button[aria-label="Diminuir quantidade"]').forEach(b=>b.onclick=()=>{quantity=Math.max(1,Math.min(99,quantity+(b.getAttribute('aria-label').startsWith('Aumentar')?1:-1)));const group=b.parentElement;const label=[...group.children].find(e=>e.tagName!=='BUTTON');if(label)label.textContent=quantity;group.querySelectorAll('button').forEach(e=>e.disabled=e.getAttribute('aria-label')?.startsWith('Diminuir')&&quantity===1)});
const gallery=main.querySelector('.gallery');if(gallery&&!gallery.querySelector('img')){const frame=gallery.querySelector('.gallery__main .swiper-wrapper');if(frame){for(const src of p.images.slice(0,8)){const slide=document.createElement('div');slide.className='gallery__main-slide';const img=document.createElement('img');img.src=src;img.alt=p.name;img.style.cssText='width:100%;height:480px;object-fit:contain';slide.append(img);frame.append(slide)}}}
const slides=[...main.querySelectorAll('.gallery__main-slide')];let imageIndex=0;function showImage(n){imageIndex=(n+slides.length)%slides.length;slides.forEach((s,i)=>{s.style.display=i===imageIndex?'block':'none';s.style.width='100%'});const track=slides[0]?.parentElement;if(track)track.style.transform='none'}if(slides.length){main.querySelectorAll('button[aria-label="Imagem anterior"],button[aria-label="Próxima imagem"]').forEach(b=>{b.disabled=false;b.removeAttribute('aria-disabled')});showImage(0);main.querySelectorAll('.gallery__thumb-slide').forEach((b,i)=>b.onclick=()=>showImage(i));main.querySelectorAll('button[aria-label="Imagem anterior"],button[aria-label="Próxima imagem"]').forEach(b=>b.onclick=()=>showImage(imageIndex+(b.getAttribute('aria-label')==='Imagem anterior'?-1:1)))}
main.querySelectorAll('button[aria-controls]').forEach(b=>{const panel=document.getElementById(b.getAttribute('aria-controls'));if(panel&&b.hasAttribute('aria-expanded'))b.onclick=()=>{const expanded=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(expanded));panel.hidden=!expanded;panel.style.display=expanded?'block':'none'}});
main.querySelectorAll('button[aria-label="Fechar vídeo informativo"]').forEach(b=>b.onclick=()=>b.parentElement.remove());
main.querySelectorAll('button').forEach(b=>{if(/^(veja a tabela nutricional)$/i.test(b.textContent.trim()))b.onclick=()=>document.getElementById('tabela-nutricional')?.scrollIntoView({behavior:'smooth'})});
document.addEventListener('submit',e=>{e.preventDefault()},true);
})();
